window.AUTH=window.AUTH||{};window.AUTH["22-1218"]={"d":"22-1218","id":"2023/22-1218","n":"Smith v. Spizzirri","briefs":[{"k":"petitioner","label":"Brief of petitioners Wendy Smith, et al.","date":"2024-02-26","url":"https://www.supremecourt.gov/DocketPDF/22/22-1218/301493/20240226231922948_22-1218%20ts.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondents Keith Spizzirri, et al.","date":"2024-03-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-1218/306049/20240327165627938_240311a%20Merits%20Brief%20for%20efiling.pdf","side":"res","n":79},{"k":"reply","label":"Reply of petitioners Wendy Smith, et al.","date":"2024-04-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-1218/307533/20240412193826158_22-1218%20rb.pdf","side":"pet","n":28}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r22_o7jq.pdf","tr":true,"items":[{"t":"case","label":"Alford v. Dean Witter Reynolds, Inc.","cite":"975 F.2d 1161","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/975/1161/","op":1,"by":{"0":"12, 15","2":"2"}},{"t":"case","label":"Anderson v. Charter Commc’ns, Inc.","cite":"860 F. App’x 374","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/860/374/","by":{"0":"11"}},{"t":"case","label":"Arabian Motors Grp. W.L.L. v. Ford Motor Co.","cite":"19 F.4th 938","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/19/938/","op":1,"by":{"0":"13, 14, 20, 21, 23"}},{"t":"case","label":"Arthur Andersen LLP v. Carlisle","cite":"556 U.S. 624","y":2009,"id":"2008/08-146","sc":1,"sum":"The Court found that regardless of whether the petitioner is eligible for a stay, a federal court of appeals has jurisdiction over a motion to stay under Section 16(a)(1) of the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"16","1":"5"}},{"t":"case","label":"Badgerow v. Walters","cite":"596 U.S. 1","y":2022,"id":"2021/20-1143","sc":1,"ar":3,"sum":"Federal jurisdiction in a petition to compel arbitration under Section 4 of the Federal Arbitration Act is determined by “looking through” the petition to the jurisdictional basis of the “underlying substantive controversy,” Vaden v. Discover Bank, 556 U. S. 49, 62, but that approach does not apply to petitions to confirm or vacate arbitral awards under Sections 9 and 10 of the FAA.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 12, 19, 21, 25","1":"2, 6, 7, 13, 19, 30, 32, 33, 40"}},{"t":"case","label":"Bedgood v. Wyndham Vacation Resorts, Inc.","cite":"88 F.4th 1355","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/88/1355/","by":{"0":"14"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"12"}},{"t":"case","label":"Cargo Carriers v. Erie & St. Lawrence Corp.","cite":"105 F. Supp. 638","y":1952,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./105/638/","by":{"0":"14"}},{"t":"case","label":"Coinbase, Inc. v. Bielski","cite":"599 U.S. 736","y":2023,"id":"2022/22-105","sc":1,"op":1,"sum":"A district court must stay its proceedings while an interlocutory appeal taken pursuant to 9 U. S. C. §16(a) on the question of arbitrability is ongoing.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 18, 19"}},{"t":"case","label":"Dean Witter Reynolds, Inc. v. Byrd","cite":"470 U.S. 213","y":1985,"id":"1984/83-1708","sc":1,"op":1,"sum":"The District Court erred in refusing to grant petitioner's motion to compel arbitration of the state claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11","1":"29, 39"}},{"t":"case","label":"Florida Dep’t of Revenue v. Piccadilly Cafeterias, Inc.","cite":"554 U.S. 33","y":2008,"id":"2007/07-312","sc":1,"sum":"The Court held 7-2 that the plain meaning of the statute indicates that it only applies to confirmed asset sales, not \"pre-confirmation\" sales.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Freeman v. SmartPay Leasing, LLC","cite":"771 F. App’x 926","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/771/926/","by":{"0":"14"}},{"t":"case","label":"Green Tree Fin. Corp.-Ala. v. Randolph","cite":"531 U.S. 79","y":2000,"id":"2000/99-1235","sc":1,"op":1,"ar":1,"sum":"The Court held that an order compelling arbitration pursuant to the parties' agreement is a \"final decision with respect to an arbitration\" within the meaning of the Federal Arbitration Act making it immediately appealable pursuant to the FAA.","sumSrc":"Oyez","by":{"0":"13","1":"3, 14, 38, 39","2":"2, 3, 5"}},{"t":"case","label":"Green v. SuperShuttle Int’l, Inc.","cite":"653 F.3d 766","y":2011,"url":"https://www.courtlistener.com/c/F.3d/653/766/","op":2,"sum":"Recognizing a district court's discretion to dismiss, rather than stay, action where all of the issues are subject to arbitration.","sumSrc":"opinion","by":{"0":"5, 11, 21, 22","1":"34","2":"1, 2"}},{"t":"case","label":"Henry Schein, Inc. v. Archer & White Sales, Inc.","cite":"139 S. Ct. 524","y":2019,"id":"2018/17-1272","sc":1,"sum":"The “wholly groundless” exception to the general rule that courts must enforce contracts that delegate threshold arbitrability questions to an arbitrator, not a court, is inconsistent with the Federal Arbitration Act and this Court’s precedent.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Inetianbor v. CashCall, Inc.","cite":"768 F.3d 1346","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/1346/","by":{"0":"15"}},{"t":"case","label":"Johnmohammadi v. Bloomingdale’s, Inc.","cite":"755 F.3d 1072","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/755/1072/","op":1,"by":{"0":"2, 4","1":"10"}},{"t":"case","label":"Katz v. Cellco P’ship","cite":"794 F.3d 341","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/794/341/","op":1,"by":{"0":"12, 20, 23"}},{"t":"case","label":"Kloeckner v. Solis","cite":"568 U.S. 41","y":2012,"id":"2012/11-184","sc":1,"sum":"The Court found that the district court, rather than the Court of Appeals, has jurisdiction over \"mixed\" cases that have been dismissed by the Merit Systems Protection Board.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"op":1,"sum":"The Court held that a district court conducting pretrial proceedings pursuant to section 1407(a) has no authority to invoke section 1404(a) to assign a transferred case to itself for trial.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Lloyd v. HOVENSA, LLC","cite":"369 F.3d 263","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/369/263/","op":1,"by":{"0":"5, 12, 20, 21"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2001,"id":"2000/99-7504","sc":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"op":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Morgan v. Sundance, Inc.","cite":"596 U.S. 411","y":2022,"id":"2021/21-328","sc":1,"sum":"Federal courts may not adopt an arbitration-specific rule conditioning a waiver of the right to arbitrate on a showing of prejudice.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16, 24"}},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"op":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 22","1":"2, 5, 6, 12, 29, 32, 39"}},{"t":"case","label":"NAVCAN.DC, Inc. v. Rinde","cite":"2023 WL 6622207","y":2023,"court":"S.D.N.Y. Oct. 11","by":{"0":"14"}},{"t":"case","label":"Pre-Paid Legal Servs., Inc. v. Cahill","cite":"786 F.3d 1287","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1287/","by":{"0":"14"}},{"t":"case","label":"Puerto Rico v. Franklin California Tax-Free Trust","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Reddam v. KPMG LLP","cite":"457 F.3d 1054","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/457/1054/","by":{"0":"15"}},{"t":"case","label":"Sparling v. Hoffman Constr. Co.","cite":"864 F.2d 635","y":1988,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/864/635/","op":1,"by":{"0":"2, 4","1":"10"}},{"t":"case","label":"Tice v. American Airlines, Inc.","cite":"288 F.3d 313","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/288/313/","by":{"0":"13, 21, 22"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"0":"11","2":"1-2, 6, 10-12, 17-19"}},{"t":"usc","label":"9 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/9/3","stext":{"head":"§3. Stay of proceedings where issue therein referable to arbitration","paras":[[0,"If any suit or proceeding be brought in any of the courts of the United States upon any issue referable to arbitration under an agreement in writing for such arbitration, the court in which such suit is pending, upon being satisfied that the issue involved in such suit or proceeding is referable to arbitration under such an agreement, shall on application of one of the parties stay the trial of the action until such arbitration has been had in accordance with the terms of the agreement, providing the applicant for the stay is not in default in proceeding with such arbitration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/3?type=usc&year=mostrecent&link-type=html"},"op":16,"ar":12,"head":"§3. Stay of proceedings where issue therein referable to arbitration","tname":"Arbitration","by":{"0":"11","1":"1-3, 6, 10-16, 18-19, 21-24, 26-28, 30-37, 39","2":"1, 3, 4, 12, 13"}},{"t":"usc","label":"9 U.S.C. § 4","url":"https://www.law.cornell.edu/uscode/text/9/4","stext":{"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","paras":[[0,"A party aggrieved by the alleged failure, neglect, or refusal of another to arbitrate under a written agreement for arbitration may petition any United States district court which, save for such agreement, would have jurisdiction under title 28, in a civil action or in admiralty of the subject matter of a suit arising out of the controversy between the parties, for an order directing that such arbitration proceed in the manner provided for in such agreement. Five days' notice in writing of such application shall be served upon the party in default. Service thereof shall be made in the manner provided by the Federal Rules of Civil Procedure. The court shall hear the parties, and upon being satisfied that the making of the agreement for arbitration or the failure to comply therewith is not in issue, the court shall make an order directing the parties to proceed to arbitration in accordance with the terms of the agreement. The hearing and proceedings, under such agreement, shall be within the district in which the petition for an order directing such arbitration is filed. If the making of the arbitration agreement or the failure, neglect, or refusal to perform the same be in issue, the court shall proceed summarily to the trial thereof. If no jury trial be demanded by the party alleged to be in default, or if the matter in dispute is within admiralty jurisdiction, the court shall hear and determine such issue. Where such an issue is raised, the party alleged to be in default may, except in cases of admiralty, on or before the return day of the notice of application, demand a jury trial of such issue, and upon such demand the court shall make an order referring the issue or issues to a jury in the manner provided by the Federal Rules of Civil Procedure, or may specially call a jury for that purpose. If the jury find that no agreement in writing for arbitration was made or that there is no default in proceeding thereunder, the proceeding shall be dismissed. If the jury find that an agreement for arbitration was made in writing and that there is a default in proceeding thereunder, the court shall make an order summarily directing the parties to proceed with the arbitration in accordance with the terms thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/4?type=usc&year=mostrecent&link-type=html"},"ar":4,"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","tname":"Arbitration","by":{"0":"11","1":"4, 6, 7, 30, 32, 39"}},{"t":"usc","label":"9 U.S.C. § 5","url":"https://www.law.cornell.edu/uscode/text/9/5","stext":{"head":"§5. Appointment of arbitrators or umpire","paras":[[0,"If in the agreement provision be made for a method of naming or appointing an arbitrator or arbitrators or an umpire, such method shall be followed; but if no method be provided therein, or if a method be provided and any party thereto shall fail to avail himself of such method, or if for any other reason there shall be a lapse in the naming of an arbitrator or arbitrators or umpire, or in filling a vacancy, then upon the application of either party to the controversy the court shall designate and appoint an arbitrator or arbitrators or umpire, as the case may require, who shall act under the said agreement with the same force and effect as if he or they had been specifically named therein; and unless otherwise provided in the agreement the arbitration shall be by a single arbitrator."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/5?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§5. Appointment of arbitrators or umpire","tname":"Arbitration","by":{"0":"21","1":"31, 33"}},{"t":"usc","label":"9 U.S.C. § 7","url":"https://www.law.cornell.edu/uscode/text/9/7","stext":{"head":"§7. Witnesses before arbitrators; fees; compelling attendance","paras":[[0,"The arbitrators selected either as prescribed in this title or otherwise, or a majority of them, may summon in writing any person to attend before them or any of them as a witness and in a proper case to bring with him or them any book, record, document, or paper which may be deemed material as evidence in the case. The fees for such attendance shall be the same as the fees of witnesses before masters of the United States courts. Said summons shall issue in the name of the arbitrator or arbitrators, or a majority of them, and shall be signed by the arbitrators, or a majority of them, and shall be directed to the said person and shall be served in the same manner as subpoenas to appear and testify before the court; if any person or persons so summoned to testify shall refuse or neglect to obey said summons, upon petition the United States district court for the district in which such arbitrators, or a majority of them, are sitting may compel the attendance of such person or persons before said arbitrator or arbitrators, or punish said person or persons for contempt in the same manner provided by law for securing the attendance of witnesses or their punishment for neglect or refusal to attend in the courts of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/7?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§7. Witnesses before arbitrators; fees; compelling attendance","tname":"Arbitration","by":{"0":"21","1":"31, 33"}},{"t":"usc","label":"9 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/9/9","stext":{"head":"§9. Award of arbitrators; confirmation; jurisdiction; procedure","paras":[[0,"If the parties in their agreement have agreed that a judgment of the court shall be entered upon the award made pursuant to the arbitration, and shall specify the court, then at any time within one year after the award is made any party to the arbitration may apply to the court so specified for an order confirming the award, and thereupon the court must grant such an order unless the award is vacated, modified, or corrected as prescribed in sections 10 and 11 of this title. If no court is specified in the agreement of the parties, then such application may be made to the United States court in and for the district within which such award was made. Notice of the application shall be served upon the adverse party, and thereupon the court shall have jurisdiction of such party as though he had appeared generally in the proceeding. If the adverse party is a resident of the district within which the award was made, such service shall be made upon the adverse party or his attorney as prescribed by law for service of notice of motion in an action in the same court. If the adverse party shall be a nonresident, then the notice of the application shall be served by the marshal of any district within which the adverse party may be found in like manner as other process of the court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/9?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9. Award of arbitrators; confirmation; jurisdiction; procedure","tname":"Arbitration","by":{"0":"21","1":"6, 7, 9, 13, 30-33, 35"}},{"t":"usc","label":"9 U.S.C. § 12","url":"https://www.law.cornell.edu/uscode/text/9/12","by":{"0":"18"}},{"t":"usc","label":"9 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/9/16","subs":["(b)(1)","(b)(2)","(a)","(a)(3)","(b)"],"stext":{"head":"§16. Appeals","paras":[[0,"(a) An appeal may be taken from—"],[1,"(1) an order—"],[2,"(A) refusing a stay of any action under section 3 of this title,"],[2,"(B) denying a petition under section 4 of this title to order arbitration to proceed,"],[2,"(C) denying an application under section 206 of this title to compel arbitration,"],[2,"(D) confirming or denying confirmation of an award or partial award, or"],[2,"(E) modifying, correcting, or vacating an award;"],[1,"(2) an interlocutory order granting, continuing, or modifying an injunction against an arbitration that is subject to this title; or"],[1,"(3) a final decision with respect to an arbitration that is subject to this title."],[0,"(b) Except as otherwise provided in section 1292(b) of title 28, an appeal may not be taken from an interlocutory order—"],[1,"(1) granting a stay of any action under section 3 of this title;"],[1,"(2) directing arbitration to proceed under section 4 of this title;"],[1,"(3) compelling arbitration under section 206 of this title; or"],[1,"(4) refusing to enjoin an arbitration that is subject to this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/16?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":4,"head":"§16. Appeals","tname":"Arbitration","by":{"0":"8, 19, 20, 20, 20","1":"2, 13-14, 27-28, 36-38, 38, 14, 13, 14, 36-38","2":"3, 17, 18"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"case","label":"Allied-Bruce Terminix Cos. v. Dobson","cite":"513 U.S. 265","y":1995,"id":"1994/93-1001","sc":1,"sum":"The Court held that the Federal Arbitration Act applied to all disputes involving commerce, and thus the arbitration clause was valid and enforceable.","sumSrc":"Oyez","by":{"1":"5, 12, 28"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Atl. Marine Constr. Co. v. U.S. Dist. Court for the W. Dist. of Tex.","cite":"571 U.S. 49","y":2013,"id":"2013/12-929","sc":1,"sum":"The Court held that the Federal Rules of Procedure allow two opposing parties in a lawsuit to transfer the litigation to a more convenient forum rather than being dismissed entirely.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Berkovitz v. Arbib & Houlberg, Inc.","cite":"230 N.Y. 261","y":1921,"url":"https://www.courtlistener.com/c/N.Y./230/261/","by":{"1":"21","2":"11"}},{"t":"case","label":"Camp v. Root","cite":"18 Johns. 22","y":1820,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Johns./18/22/","by":{"1":"23"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 25, 27","2":"17"}},{"t":"case","label":"Claflin v. Meyer","cite":"75 N.Y. 260","y":1878,"url":"https://www.courtlistener.com/c/N.Y./75/260/","by":{"1":"24"}},{"t":"case","label":"Cortez Byrd Chips, Inc. v. Bill Harbert Constr. Co.","cite":"529 U.S. 193","y":2000,"id":"1999/98-1960","sc":1,"ar":2,"sum":"Delivered by Justice David H. Souter, the Court held that the \"FAA's venue provisions are permissive, allowing a motion to confirm, vacate, or modify to be brought either in the district where the award was made or in any district proper under the general venue statute.\" Writing for the Court, Justice Souter reasoned that because both the history and function of the FAA's venue provisions dictate that they were meant to expand, not limit, venue choice, it was appropriate for Cortez Byrd to seek to vacate the arbitrator's award in federal court in Mississippi.","sumSrc":"Oyez","by":{"1":"36","2":"20"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Dep’t of Homeland Sec. v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Dietz v. Bouldin","cite":"579 U.S. 40","y":2016,"id":"2015/15-458","sc":1,"sum":"The Court determined that a federal district court judge has some ability to recall jurors in a civil case after identifying an error in their verdict, subject to certain limitations to ensure the jurors were not prejudiced.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Dir. of Revenue of Missouri v. CoBank ACB","cite":"531 U.S. 316","y":2001,"id":"2000/99-1792","sc":1,"sum":"The Court held that banks for cooperatives are subject to taxation. Justice Thomas wrote for the Court that nothing in the 1985 amendments to the Farm Credit Act indicated a repeal of the previous express approval of state taxation and that the structure of the Act indicated by negative implication that banks for cooperatives were not entitled to immunity.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Draghicevich v. Vulicevich","cite":"18 P. 406","y":1888,"court":"Cal.","url":"https://www.courtlistener.com/c/P./18/406/","by":{"1":"23"}},{"t":"case","label":"Edmonds v. Compagnie Generale Transatlantique","cite":"443 U.S. 256","y":1979,"id":"1978/78-479","sc":1,"sum":"Petitioner longshoreman, while employed by a stevedoring concern that respondent shipowner -had engaged to unload cargo from its vessel, was injured in the course of that work, and received benefits for the injury from his employer under the Longshoremen's and Harbor Workers' Compensation Act (Act). Petitioner also brought this negligence action against respondent in Federal District Court, wherein the jury …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Far East Conf. v. United States","cite":"342 U.S. 570","y":1952,"id":"scdb/1951-055","sc":1,"sum":"The United States brought this suit in the District Court to enjoin alleged violations of the Sherman Antitrust Act. The defendants were the Far East Conference, a voluntary association, and its constituent members, steanship companies engaged in \"outbound Far East trade.\" The agreement under which the Conference operated was approved by the predecessor of the Federal Maritime Boar d, exercising authority under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Fransden v. Bhd. of Ry., Airline & S.S. Clerks","cite":"782 F.2d 674","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/782/674/","by":{"1":"34"}},{"t":"case","label":"Galindo v. Stoody Co.","cite":"793 F.2d 1502","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/793/1502/","by":{"1":"34"}},{"t":"case","label":"Gilmer v. Interstate/Johnson Lane Corp.","cite":"500 U.S. 20","y":1991,"id":"1990/90-18","sc":1,"sum":"An ADEA claim can be subjected to compulsory arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Gulf Oil Corp. v. Gilbert","cite":"330 U.S. 501","y":1947,"id":"scdb/1946-068","sc":1,"sum":"It did not abuse its discretion in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25, 26, 27"}},{"t":"case","label":"Gunter v. Sanchez","cite":"1 Cal. 45","y":1850,"url":"https://www.courtlistener.com/c/Cal./1/45/","by":{"1":"24"}},{"t":"case","label":"Hall St. Assocs., L.L.C. v. Mattel, Inc.","cite":"552 U.S. 576","y":2008,"id":"2007/06-989","sc":1,"sum":"The Court affirmed the Ninth Circuit ruling and held that the provisions of the FAA are exclusive and cannot be expanded through contractual agreement. Writing for the majority, Justice David Souter pointed to words such as \"must\" and \"unless\" in the FAA as evidence that its provisions were intended to be mandatory and incapable of modification by the parties.","sumSrc":"Oyez","by":{"1":"6, 21, 30, 32"}},{"t":"case","label":"Heslep v. City of San Francisco","cite":"4 Cal. 1","y":1852,"url":"https://www.courtlistener.com/c/Cal./4/1/","by":{"1":"24"}},{"t":"case","label":"Hopkins & Carley, ALC v. Thomson Elite","cite":"2011 WL 1327359","y":2011,"court":"N.D. Cal. Apr. 6","by":{"1":"35"}},{"t":"case","label":"Ins. Co. of N. Am. v. ABB Power Generation, Inc.","cite":"925 F. Supp. 1053","y":1996,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./925/1053/","by":{"1":"35"}},{"t":"case","label":"Kelvin Eng’g Co. v. Blanco","cite":"125 Misc. 728","y":1925,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Misc./125/728/","by":{"1":"21","2":"11"}},{"t":"case","label":"Landis v. N. Am. Co.","cite":"299 U.S. 248","y":1936,"id":"scdb/1936-018","sc":1,"sum":"(1) That to grant the stay until decision of the other case by this Court on appeal, was abuse of discretion. P. 256. (2) The question whether the stay would have been proper under the conditions which existed when it was granted, had it been granted to continue only until decision of the other case by the District Court, is a question which this Court will not decide, because the conditions have changed. P. 258. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Larkin v. Robbins","cite":"2 Wend. 505","y":1829,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Wend./2/505/","by":{"1":"24"}},{"t":"case","label":"Link v. Wabash R.R. Co.","cite":"370 U.S. 626","y":1962,"id":"1961/422","sc":1,"sum":"The Court held that a court has the right to clear its calendar of cases that have been dormant because of inaction on the part of the plaintiff without any motion from the defense. This right has long been understood as one of the inherent powers of the court and no law explicitly restricts it.","sumSrc":"Oyez","by":{"1":"25, 26, 27","2":"15"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Martin Marietta Aluminum, Inc. v. Gen. Elec. Co.","cite":"586 F.2d 143","y":1978,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/586/143/","by":{"1":"10"}},{"t":"case","label":"People ex rel. Martin v. Cnty. of Westchester","cite":"53 A.D. 339","y":1900,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D./53/339/","by":{"1":"24"}},{"t":"case","label":"McNulty v. Solley","cite":"95 N.Y. 242","y":1884,"url":"https://www.courtlistener.com/c/N.Y./95/242/","by":{"1":"23","2":"11"}},{"t":"case","label":"Midlantic Nat’l Bank v. New Jersey Dep’t of Envt’l Protection","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Mooers v. Allen","cite":"35 Me. 276","y":1853,"url":"https://www.courtlistener.com/c/Me./35/276/","by":{"1":"24"}},{"t":"case","label":"Niagara Falls & L.R. Co. v. Brundage","cite":"7 A.D. 445","y":1896,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D./7/445/","by":{"1":"24"}},{"t":"case","label":"Prima Paint Corp. v. Flood & Conklin Mfg. Co.","cite":"388 U.S. 395","y":1967,"id":"1966/343","sc":1,"sum":"Describing “the unmistakably clear congressional purpose that the arbitration procedure, when selected by the parties to a contract, be speedy and not subject to delay and obstruction in the courts”.","sumSrc":"brief:1","by":{"1":"39"}},{"t":"case","label":"Radway v. Duffy","cite":"79 A.D. 116","y":1903,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D./79/116/","by":{"1":"24"}},{"t":"case","label":"Red Cross Line v. Atl. Fruit Co.","cite":"264 U.S. 109","y":1924,"id":"scdb/1923-067","sc":1,"sum":"1. A decision of the highest court of a State excluding maritime contracts from the operation of a state statute, not as a matter of statutory construction but due to its opinion that the Federal Constitution so requires, presents a constitutional question reviewable here.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 4, 28"}},{"t":"case","label":"Reiter v. Cooper","cite":"507 U.S. 258","y":1993,"id":"1992/91-1496","sc":1,"sum":"The Interstate Commerce Act (ICA) requires that motor common carriers charge the tariff rates they file with the Interstate Commerce Commission (ICC), 49 U. S. C. § 10762, and that such rates be \"reasonable,\" § 10701(a). Between 1984 and 1986, petitioner shippers tendered shipments to Carolina Motor Express, Inc., a motor carrier subject to ICC regulation, at negotiated rates that were lower than the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17","2":"8"}},{"t":"case","label":"Rowland v. Patterson","cite":"882 F.2d 97","y":1989,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/882/97/","by":{"1":"34","2":"19"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"1":"26, 29"}},{"t":"case","label":"Shanferoke Coal & Supply Corp. v. Westchester Serv. Corp.","cite":"293 U.S. 449","y":1935,"id":"scdb/1934-101","sc":1,"sum":"1. Denial by the District Court of an application for a stay of proceedings in an action on a contract until an arbitration shall be had in accordance with the terms of the contract, is in effect an order denying an interlocutory injunction, and is appealable, under Jud. Code, § 129, to the Circuit Court of Appeals. Endow v. New York Life Ins. Co., ante, p. 379.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"SmartSky Networks, LLC v. DAG Wireless, LTD.","cite":"93 F.4th 175","y":2024,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/93/175/","by":{"1":"33"}},{"t":"case","label":"Smith v. Spizzirri","cite":"2022 WL 4537940","y":2022,"court":"9th Cir. Sept. 20","by":{"1":"8"}},{"t":"case","label":"Southland Corp. v. Keating","cite":"465 U.S. 1","y":1984,"id":"1983/82-500","sc":1,"sum":"Appellant Southland Corp. (hereafter appellant) is the owner and franchisor of 7-Eleven convenience stores. Appellees are 7-Eleven franchisees. Each franchise agreement between appellant and appellees contains a clause requiring arbitration of any controversy or claim arising out of or relating to the agreement or breach thereof. Several of the appellees filed individual actions against appellant in California …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Spates v. Uber Techs., Inc.","cite":"2023 WL 3506138","y":2023,"court":"S.D.N.Y. Mar. 31","by":{"1":"40"}},{"t":"case","label":"State Farm Mut. Auto. Ins. Co. v. Diaz","cite":"223 A.D.3d 674","y":2024,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D.3d/223/674/","by":{"1":"18","2":"10"}},{"t":"case","label":"Stewart v. Acer Inc.","cite":"2023 WL 1463413","y":2023,"court":"N.D. Cal. Feb. 1","by":{"1":"34"}},{"t":"case","label":"The Anaconda v. Am. Sugar Ref. Co.","cite":"322 U.S. 42","y":1944,"id":"scdb/1943-051","sc":1,"sum":"The parties to an agreement for arbitration of disputes arising out of a charter party can not by stipulation make unavailable the right of the aggrieved party under § 8 of the United States Arbitration Act to begin his proceeding by \"libel and seizure of the vessel... according to the usual course of admiralty proceedings.\" P. 46. 138 F. 2d 765, affirmed. CEmTIORARI, 321 U. S. 758, to review the reversal of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Thinket Ink Info. Res., Inc. v. Sun Microsystems, Inc.","cite":"368 F.3d 1053","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/368/1053/","by":{"1":"10"}},{"t":"case","label":"Travelers’ Ins. Co. v. Pierce Engine Co.","cite":"123 N.W. 643","y":1909,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./123/643/","by":{"1":"23"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"29"}},{"t":"case","label":"Vaden v. Discover Bank","cite":"556 U.S. 49","y":2009,"id":"2008/07-773","sc":1,"sum":"The Court held that a federal court may \"look through\" a Section 4 petition to determine whether the claim establishes federal subject matter jurisdiction.","sumSrc":"Oyez","by":{"1":"6, 30, 32"}},{"t":"case","label":"Volt Info. Scis., Inc. v. Bd. of Trs. of Leland Stanford Junior Univ.","cite":"489 U.S. 468","y":1989,"id":"1988/87-1318","sc":1,"sum":"A construction contract between appellant and appellee contained an agreement to arbitrate all disputes arising out of the contract and a choice-of-law clause providing that the contract would be governed by the law of \"the place where the Project is located.\" When a dispute arose under the contract, appellant made a formal demand for arbitration. In response, appellee filed an action against appellant in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"Wells v. Lain","cite":"15 Wend. 99","y":1835,"court":"N.Y.","url":"https://www.courtlistener.com/c/Wend./15/99/","by":{"1":"24"}},{"t":"usc","label":"9 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/9/2","stext":{"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","paras":[[0,"A written provision in any maritime transaction or a contract evidencing a transaction involving commerce to settle by arbitration a controversy thereafter arising out of such contract or transaction, or the refusal to perform the whole or any part thereof, or an agreement in writing to submit to arbitration an existing controversy arising out of such a contract, transaction, or refusal, shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract or as otherwise provided in chapter 4."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/2?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","tname":"Arbitration","by":{"1":"5, 28"}},{"t":"usc","label":"9 U.S.C. § 8","url":"https://www.law.cornell.edu/uscode/text/9/8","stext":{"head":"§8. Proceedings begun by libel in admiralty and seizure of vessel or property","paras":[[0,"If the basis of jurisdiction be a cause of action otherwise justiciable in admiralty, then, notwithstanding anything herein to the contrary, the party claiming to be aggrieved may begin his proceeding hereunder by libel and seizure of the vessel or other property of the other party according to the usual course of admiralty proceedings, and the court shall then have jurisdiction to direct the parties to proceed with the arbitration and shall retain jurisdiction to enter its decree upon the award."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/8?type=usc&year=mostrecent&link-type=html"},"ar":4,"head":"§8. Proceedings begun by libel in admiralty and seizure of vessel or property","tname":"Arbitration","by":{"1":"2, 11-12, 19-20, 27-28","2":"18"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","by":{"1":"6, 7, 13, 30-33, 36"}},{"t":"usc","label":"9 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/9/11","by":{"1":"4, 6, 7, 31-33, 36"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(a)(1)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"1":"17","2":"9"}},{"t":"usc","label":"28 U.S.C. § 476","url":"https://www.law.cornell.edu/uscode/text/28/476","by":{"1":"41"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"1":"14, 36","2":"18"}},{"t":"case","label":"Branch v. Smith","cite":"538 U.S. 254","y":2003,"id":"2002/01-1437","sc":1,"sum":"The Court held, 9-0, that the District Court properly enjoined enforcement of the state- court plan that lacked the required timely preclearance.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Marine Transit Corp. v. Dreyfus","cite":"284 U.S. 263","y":1932,"id":"scdb/1931-142","sc":1,"sum":"Cargo was lost through the alleged fault of the.carrier while being towed in. a canal-a navigable water of the United. States-under a fiaritime contract providing that all dispiltes under it should be arbitrated before a designated board,- whose -decision -hould *be final and binding..The cargo owners, proceeding in a District Court of the United States in admiralty, filed a libel for damages against the carrier and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"(I) Cases—continued: Rodriguez v. FDIC","cite":"589 U.S. 132","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/132/","sc":1,"by":{"2":"16"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"United States Ass’n of Tex. v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Vermont Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Wilson v. Glasgow Tramways & Omnibus Co.","cite":"5 R. 981","y":1878,"court":"Scot.","url":"https://www.courtlistener.com/c/R./5/981/","by":{"2":"10"}},{"t":"case","label":"Zimmerman, Matter of v. Cohen","cite":"236 N.Y. 15","y":1923,"url":"https://www.courtlistener.com/c/N.Y./236/15/","by":{"2":"10"}},{"t":"usc","label":"28 U.S.C. § 1367","url":"https://www.law.cornell.edu/uscode/text/28/1367","by":{"2":"19"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","by":{"2":"13"}}]};